def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]

    # Find full rows or columns that act as separators.
    for axis in (0, 1):
        n = h if axis == 0 else w
        m = w if axis == 0 else h
        separators = []
        for i in range(n):
            line = [grid[i][j] for j in range(m)] if axis == 0 else [grid[j][i] for j in range(m)]
            if line and len(set(line)) == 1 and line[0] != bg:
                separators.append(i)

        if not separators:
            continue

        bounds = [-1] + separators + [n]
        segments = [(bounds[k] + 1, bounds[k + 1]) for k in range(len(bounds) - 1)]
        lengths = [b - a for a, b in segments]
        if not lengths or len(set(lengths)) != 1 or lengths[0] == 0:
            continue

        out = [row[:] for row in grid]
        L = lengths[0]
        for offset in range(L):
            for j in range(m):
                vals = []
                for a, b in segments:
                    r = a + offset
                    v = grid[r][j] if axis == 0 else grid[j][r]
                    if v != bg:
                        vals.append(v)
                if vals:
                    v = vals[0]
                    for a, b in segments:
                        r = a + offset
                        if axis == 0:
                            out[r][j] = v
                        else:
                            out[j][r] = v
        return out

    return [row[:] for row in grid]
